from moler.cmd.unix.exit import Exit as GenericExit

__author__ = 'Tomasz Krol'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'tomasz.krol@nokia.com'


class Exit(GenericExit):
    """Exit command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None, expected_prompt=r"toor4nsn@fzhub:.*#", **kwargs):
        """
        Exit from rfsw_cli state.

        :param connection: moler connection to device, terminal when command is executed
        :param prompt: Prompt of the starting shell
        :param expected_prompt: Prompt of the target shell reached after exit from rfsw_cli state
        :param newline_chars: Characters to split lines
        """
        super(Exit, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                   runner=runner, expected_prompt=expected_prompt, **kwargs)


COMMAND_OUTPUT = """
rfsw> exit
toor4nsn@fzhub:~#"""

COMMAND_KWARGS = {
    "expected_prompt": r'toor4nsn@fzhub:.*#'
}

COMMAND_RESULT = {}
